(()=>{'use strict';const form=document.getElementById('technical-filter');if(!form)return;const q=document.getElementById('technical-query'),cat=document.getElementById('technical-category'),review=document.getElementById('technical-review'),result=document.getElementById('technical-results'),status=document.getElementById('technical-status'),more=document.getElementById('technical-more'),clear=document.getElementById('technical-clear'),empty=document.getElementById('technical-empty');let records=[],checked=new Set(),limit=18;const norm=s=>s.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');
function state(){const p=new URLSearchParams();if(q.value.trim())p.set('q',q.value.trim());if(cat.value!=='all')p.set('category',cat.value);if(review.value!=='all')p.set('review',review.value);history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():''));}
function restore(){const p=new URLSearchParams(location.search);q.value=(p.get('q')||'').slice(0,200);for(const [key,el]of [['category',cat],['review',review]]){const v=p.get(key);el.value=[...el.options].some(o=>o.value===v)?v:'all';}}
function render(){const tokens=norm(q.value).split(/\s+/).filter(Boolean),found=records.filter(a=>(cat.value==='all'||a.category===cat.value)&&(review.value==='all'||checked.has(a.url.replace(/\.html$/,'')))&&tokens.every(t=>norm(a.title+' '+a.description).includes(t)));result.replaceChildren();found.slice(0,limit).forEach(a=>{const box=document.createElement('article'),h=document.createElement('h2'),link=document.createElement('a'),p=document.createElement('p'),badge=document.createElement('p');box.className='growth-card';if(!/^\/blog\/[^\s?#]+$/u.test(a.url))return;link.href=a.url;link.textContent=a.title;h.append(link);p.textContent=a.description;badge.textContent=a.category+(checked.has(a.url.replace(/\.html$/,''))?' · Kaynaklı inceleme · tarih yazıda belirtilir':'');box.append(badge,h,p);result.append(box)});status.textContent=found.length+' sonuç · '+Math.min(found.length,limit)+' gösteriliyor';more.hidden=found.length<=limit;empty.hidden=found.length>0;clear.hidden=!(q.value||cat.value!=='all'||review.value!=='all');state();}
function reset(){q.value='';cat.value=review.value='all';limit=18;render();q.focus();}form.addEventListener('submit',e=>{e.preventDefault();limit=18;render()});[q,cat,review].forEach(el=>el.addEventListener(el===q?'input':'change',()=>{limit=18;render()}));more.addEventListener('click',()=>{limit+=18;render()});clear.addEventListener('click',reset);document.getElementById('technical-empty-clear').addEventListener('click',reset);window.addEventListener('popstate',()=>{restore();limit=18;render()});
Promise.all([fetch('/assets/content-index.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('/assets/editorial-reviewed-20261015.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([data,done])=>{records=data.filter(a=>a.kind==='editorial');checked=new Set(done);restore();render()}).catch(()=>{status.textContent='Arama dizini yüklenemedi. Blog koleksiyonu ve teknik kütüphaneyi kullanabilirsiniz.';empty.hidden=false;empty.querySelector('h2').textContent='Arama şu anda yüklenemedi';empty.querySelector('p').textContent='Yazıları blog sayfasından inceleyebilir veya daha sonra yeniden deneyebilirsiniz.';document.getElementById('technical-empty-clear').hidden=true;});})();